export { Input, type InputProps } from "./input";
export {
	type InputGroupContextValue,
	InputGroupProvider,
	useInputGroup,
	useInputGroupContext,
} from "./input.context";
export type { InputSlotProps } from "./input.types";
export {
	INPUT_DECORATOR_ICON_TOKEN,
	INPUT_INVALID_DECORATOR_ICON_TOKEN,
	INPUT_INVALID_SELECTION_ACCENT_CLASS,
	INPUT_PLACEHOLDER_ACCENT_CLASS,
	INPUT_SELECTION_ACCENT_CLASS,
	INPUT_SIZES,
	INPUT_VARIANTS,
	type InputBoxState,
	type InputSize,
	type InputVariant,
	type InputVariantProps,
	inputVariants,
	resolveInputFieldClass,
	resolveInputGroupClass,
	resolvePlaceholderAccentClass,
	resolveSelectionAccentClass,
} from "./input.variants";
export type { InputGroupProps } from "./input-group";

import { Children, type ReactElement, type ReactNode, useMemo } from "react";
import { View } from "react-native";
import { IconDefaultsProvider } from "@registry/ui/icon";
import { Text } from "@registry/ui/text";
import { TextClassProvider } from "@registry/ui/text/text.context";
import { useInputGroupPart } from "./input.context";
import type { InputSlotProps } from "./input.types";
import { INPUT_DECORATOR_ICON_TOKEN, INPUT_INVALID_DECORATOR_ICON_TOKEN, inputVariants } from "./input.variants";

/**
 * The shared implementation behind `Input.Group.Prefix` and `.Suffix`.
 *
 * The two are the same box in different places — the row's `gap` is what puts
 * them either side of the field, not a class of their own — so they read one
 * `decorator` slot and share this file. Duplicating {@link wrapTextChildren}
 * into two part files to keep them apart is exactly what this leaf avoids.
 *
 * Not a part itself: it takes the caller-facing name so the error thrown
 * outside a group names `Input.Group.Prefix` rather than something private.
 */
export function InputGroupDecorator({
	part,
	className,
	children,
	...props
}: InputSlotProps & { part: string }): ReactElement {
	const { isInvalid, size } = useInputGroupPart(part);
	const slots = inputVariants({ isInvalid, size });

	const iconClassName = slots.decoratorIcon();
	const iconDefaults = useMemo(
		() => ({
			className: iconClassName,
			color: isInvalid ? INPUT_INVALID_DECORATOR_ICON_TOKEN : INPUT_DECORATOR_ICON_TOKEN,
		}),
		[iconClassName, isInvalid]
	);

	return (
		<View className={slots.decorator({ className })} {...props}>
			<IconDefaultsProvider value={iconDefaults}>
				<TextClassProvider value={slots.decoratorText()}>{wrapTextChildren(children)}</TextClassProvider>
			</IconDefaultsProvider>
		</View>
	);
}
InputGroupDecorator.displayName = "DelacourUI.Input.Group.Decorator";

/**
 * Wraps bare text children in a `Text`.
 *
 * A decorator renders a `View`, and React Native cannot render a string outside
 * a `<Text>` — so `<Input.Group.Prefix>$</Input.Group.Prefix>`, which is the
 * shortest thing anyone will write, would otherwise crash. Consecutive strings
 * and numbers are collected into one `Text` rather than one each, so a
 * `{currency}{symbol}` pair is a single affix instead of two spaced apart by
 * nothing.
 *
 * The wrapped text needs no className: the decorator has already published the
 * affix treatment through `TextClassProvider`.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(<Text key={`affix-${output.length}`}>{run.join("")}</Text>);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

import type { ReactElement } from "react";
import type { InputSlotProps } from "./input.types";
import { InputGroupDecorator } from "./input-group-decorator";

/**
 * Leading content inside the field's own box — an icon, a text affix, a control.
 *
 * An `Icon` needs nothing said at the call site: it inherits the field's icon
 * step and a muted colour from the decorator's `IconDefaultsProvider`, and turns
 * danger with the group when the value is invalid. A bare string is wrapped in a
 * `Text` that inherits the same affix treatment.
 */
export function InputGroupPrefix(props: InputSlotProps): ReactElement {
	return <InputGroupDecorator part="Input.Group.Prefix" {...props} />;
}
InputGroupPrefix.displayName = "DelacourUI.Input.Group.Prefix";

import type { ReactElement } from "react";
import type { InputSlotProps } from "./input.types";
import { InputGroupDecorator } from "./input-group-decorator";

/**
 * Trailing content inside the field's own box — an icon, a text affix, a control.
 *
 * Draws nothing of its own, unlike `ListGroup.ItemSuffix`: a row in a list has a
 * default chevron because it always navigates, whereas a field's trailing slot
 * has no one thing it usually holds.
 */
export function InputGroupSuffix(props: InputSlotProps): ReactElement {
	return <InputGroupDecorator part="Input.Group.Suffix" {...props} />;
}
InputGroupSuffix.displayName = "DelacourUI.Input.Group.Suffix";

import { type ReactElement, type ReactNode, useCallback, useMemo, useRef, useState } from "react";
import type { TextInput } from "react-native";
import { useFieldContext } from "@registry/ui/field/field.context";
import { Pressable } from "@registry/ui/pressable";
import { type InputGroupContextValue, InputGroupProvider } from "./input.context";
import { type InputSize, type InputVariant, resolveInputGroupClass } from "./input.variants";
import { InputGroupPrefix } from "./input-group-prefix";
import { InputGroupSuffix } from "./input-group-suffix";

export type InputGroupProps = {
	/** Visual variant of the box. Read by the `Input` inside it. */
	variant?: InputVariant;
	/** Size of the box, the field's type scale and a decorator's icon. */
	size?: InputSize;
	/**
	 * Reports an invalid value: the border, the caret and the decorators all turn
	 * danger. Inherited from an enclosing `Field` when it is not given.
	 */
	isInvalid?: boolean;
	/**
	 * Disables the field inside and fades the whole box. Inherited from an
	 * enclosing `Field` when it is not given.
	 */
	isDisabled?: boolean;
	className?: string;
	children?: ReactNode;
};

function InputGroupRoot({
	variant = "primary",
	size = "md",
	isInvalid,
	isDisabled,
	className,
	children,
}: InputGroupProps): ReactElement {
	const fieldRef = useRef<TextInput | null>(null);
	const field = useFieldContext();
	const [isFocused, setFocused] = useState(false);

	// An enclosing `Field` is the outermost source, so it is the last fallback:
	// a group inside an invalid field turns danger with it, and a group that
	// names its own state overrides that. These are deliberately not defaulted
	// in the destructure — `false` there would swallow the field before it was
	// ever consulted.
	const resolvedIsInvalid = isInvalid ?? field?.isInvalid ?? false;
	const resolvedIsDisabled = isDisabled ?? field?.isDisabled ?? false;

	const context = useMemo<InputGroupContextValue>(
		() => ({
			fieldRef,
			isDisabled: resolvedIsDisabled,
			isFocused,
			isInvalid: resolvedIsInvalid,
			setFocused,
			size,
			variant,
		}),
		[resolvedIsDisabled, isFocused, resolvedIsInvalid, size, variant]
	);

	// A lone field is its own tap target edge to edge. Inside a group the field
	// only covers the middle of the box, so the gutter and the space around a
	// decorator have to hand the press on rather than swallow it.
	const focusField = useCallback(() => fieldRef.current?.focus(), []);

	return (
		<InputGroupProvider value={context}>
			<Pressable
				accessible={false}
				className={resolveInputGroupClass({
					className,
					isDisabled: resolvedIsDisabled,
					isFocused,
					isInvalid: resolvedIsInvalid,
					size,
					variant,
				})}
				disabled={resolvedIsDisabled}
				feedback="none"
				onPress={focusField}
			>
				{children}
			</Pressable>
		</InputGroupProvider>
	);
}

/**
 * A field with content inside its box — a leading icon, a trailing control, a
 * text affix, or all three.
 *
 * The box is the same one a lone `Input` draws. It is not a copy: both read the
 * one `root` slot of `inputVariants`, which lands on the `TextInput` when a
 * field stands alone and on this row when it does not. A grouped field is
 * therefore indistinguishable from an ungrouped one by construction, and
 * `input.variants.test.ts` pins that as a property rather than a comment.
 *
 * The group owns the box, so it owns the axes that draw one — `variant`, `size`,
 * `isInvalid`, `isDisabled` all live here and the `Input` inside reads them from
 * context. One box, one set of axes.
 *
 * Pressing the box focuses the field, so the gutter behaves the way a lone
 * field's does. A control inside a decorator still receives its own press.
 *
 * @example
 * <Input.Group>
 *   <Input.Group.Prefix>
 *     <Icon icon={IconMagnifyingGlass} />
 *   </Input.Group.Prefix>
 *   <Input placeholder="Search" />
 * </Input.Group>
 *
 * @example
 * <Input.Group size="lg">
 *   <Input.Group.Prefix>$</Input.Group.Prefix>
 *   <Input inputMode="decimal" placeholder="0.00" />
 *   <Input.Group.Suffix>NZD</Input.Group.Suffix>
 * </Input.Group>
 */
export const InputGroup = Object.assign(InputGroupRoot, {
	/** Leading content inside the box. An `Icon` or a bare string needs nothing else. */
	Prefix: InputGroupPrefix,
	/** Trailing content inside the box — a clear button, a unit, a reveal toggle. */
	Suffix: InputGroupSuffix,
	displayName: "DelacourUI.Input.Group",
});

import { createContext, type ReactElement, type ReactNode, type RefObject, use } from "react";
import type { TextInput } from "react-native";
import type { InputSize, InputVariant } from "./input.variants";

export type InputGroupContextValue = {
	/** Visual variant of the box every part of the group sits in. */
	variant: InputVariant;
	/** Size of the box, which also drives the field's type scale and a decorator's icon. */
	size: InputSize;
	/** Whether the group reports an invalid value. */
	isInvalid: boolean;
	/** Whether the group is disabled. */
	isDisabled: boolean;
	/** Whether the field inside the group holds focus. */
	isFocused: boolean;
	/** Reported by the field on focus and blur, so the box can light up around it. */
	setFocused: (isFocused: boolean) => void;
	/**
	 * The field the group wraps, so tapping the box's gutter can focus it.
	 *
	 * A lone field is the whole tap target; inside a group the field only covers
	 * the middle of the box, and a tap on the padding either side would otherwise
	 * do nothing.
	 */
	fieldRef: RefObject<TextInput | null>;
};

const InputGroupContext = createContext<InputGroupContextValue | null>(null);

/**
 * Supplies the enclosing group's box, state and field ref to its subtree.
 *
 * The group owns the box, so it owns the axes that draw one: an `Input` inside
 * a group reads `variant`, `size`, `isInvalid` and `isDisabled` from here rather
 * than from its own props, the same way a `ListGroup.Item` takes no `variant`.
 * One box, one set of axes — two would be two things that can disagree.
 *
 * Lives in its own module, importing nothing but React and a type-only
 * `TextInput`, so `input.tsx` can read it without importing `./input-group` and
 * closing a cycle back through the root. See AGENTS.md rule 3.
 */
export function InputGroupProvider({
	value,
	children,
}: {
	value: InputGroupContextValue;
	children: ReactNode;
}): ReactElement {
	return <InputGroupContext value={value}>{children}</InputGroupContext>;
}
InputGroupProvider.displayName = "DelacourUI.Input.Group.Provider";

/** The enclosing group's context, or null for a field standing on its own. */
export function useInputGroupContext(): InputGroupContextValue | null {
	return use(InputGroupContext);
}

/**
 * Reads the enclosing `Input.Group`'s box and state.
 *
 * For a custom part that has to match the group it sits in. Throws outside one —
 * use {@link useInputGroupContext} where the group is optional, as `Input`
 * itself does.
 */
export function useInputGroup(): InputGroupContextValue {
	const context = useInputGroupContext();
	if (!context) {
		throw new Error("useInputGroup must be called inside an <Input.Group>.");
	}
	return context;
}

/**
 * The enclosing group's context, for a compound part that cannot work without
 * one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useInputGroup}, whose error message names the hook rather
 * than a part.
 */
export function useInputGroupPart(component: string): InputGroupContextValue {
	const context = useInputGroupContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside an <Input.Group>.`);
	}
	return context;
}

import { type ReactElement, type Ref, useCallback, useState } from "react";
import { TextInput, type TextInputProps } from "react-native";
import { composeRefs } from "@registry/lib/compose-refs";
import { useFieldContext } from "@registry/ui/field/field.context";
import { useInputGroupContext } from "./input.context";
import {
	type InputSize,
	type InputVariant,
	resolveInputFieldClass,
	resolvePlaceholderAccentClass,
	resolveSelectionAccentClass,
} from "./input.variants";
import { InputGroup } from "./input-group";

/**
 * The events React Native hands a field's focus and blur callbacks.
 *
 * Read off `TextInputProps` rather than named outright: React Native renamed
 * these between versions, and a restated type would go stale silently — the
 * handler would still compile against the old shape and fail to match the prop.
 */
type InputFocusEvent = Parameters<NonNullable<TextInputProps["onFocus"]>>[0];
type InputBlurEvent = Parameters<NonNullable<TextInputProps["onBlur"]>>[0];

export type InputProps = Omit<TextInputProps, "placeholderTextColorClassName"> & {
	/** Visual variant of the box. Ignored inside an `Input.Group`, which owns the box. */
	variant?: InputVariant;
	/** Size of the box and the value's type scale. Ignored inside an `Input.Group`. */
	size?: InputSize;
	/**
	 * Reports an invalid value. Ignored inside an `Input.Group`, which owns it;
	 * inherited from an enclosing `Field` when neither names it.
	 */
	isInvalid?: boolean;
	/**
	 * Blocks editing and fades the field. Ignored inside an `Input.Group`, which
	 * owns it; inherited from an enclosing `Field` when neither names it.
	 */
	isDisabled?: boolean;
	/**
	 * Placeholder colour, as an `accent-*` utility — `accent-muted-foreground`.
	 * Any other utility resolves to nothing; see `input.variants.ts`.
	 */
	placeholderColorClassName?: string;
	/**
	 * Caret and selection colour, as an `accent-*` utility. Defaults to the
	 * primary token, or the danger one while the field is invalid.
	 */
	selectionColorClassName?: string;
	ref?: Ref<TextInput>;
};

function InputRoot({
	variant,
	size,
	isInvalid,
	isDisabled,
	className,
	placeholderColorClassName,
	selectionColorClassName,
	editable,
	multiline,
	onBlur,
	onFocus,
	ref,
	...props
}: InputProps): ReactElement {
	const group = useInputGroupContext();
	const field = useFieldContext();
	const [ownFocused, setOwnFocused] = useState(false);

	// Nearest wins, and there are three sources for the two state axes.
	//
	// Inside a group the box belongs to the group, so the axes that draw one do
	// too — the same way a `ListGroup.Item` takes no `variant`. An enclosing
	// `Field` is the outermost of the three and therefore the last fallback, so
	// a field with no props of its own turns danger with the `Field` around it
	// while `<Input isInvalid={false} />` still opts out of one.
	const resolved = {
		isDisabled: group?.isDisabled ?? isDisabled ?? field?.isDisabled ?? false,
		isInvalid: group?.isInvalid ?? isInvalid ?? field?.isInvalid ?? false,
		size: group?.size ?? size ?? "md",
		variant: group?.variant ?? variant ?? "primary",
	};

	// The group's box has to light up around a field it does not contain the
	// focus of, so focus is reported upward when there is a group and held here
	// when there is not. Picking the setter is a plain branch, not a hook, so
	// hook order is the same either way.
	const isFocused = group ? group.isFocused : ownFocused;
	const setFocused = group ? group.setFocused : setOwnFocused;

	const handleFocus = useCallback(
		(event: InputFocusEvent) => {
			setFocused(true);
			onFocus?.(event);
		},
		[onFocus, setFocused]
	);

	const handleBlur = useCallback(
		(event: InputBlurEvent) => {
			setFocused(false);
			onBlur?.(event);
		},
		[onBlur, setFocused]
	);

	const selectionAccent = resolveSelectionAccentClass({
		className: selectionColorClassName,
		isInvalid: resolved.isInvalid,
	});

	return (
		<TextInput
			className={resolveInputFieldClass({
				...resolved,
				className,
				isFocused,
				isGrouped: group !== null,
				isMultiline: multiline === true,
			})}
			cursorColorClassName={selectionAccent}
			multiline={multiline}
			placeholderTextColorClassName={resolvePlaceholderAccentClass(placeholderColorClassName)}
			selectionColorClassName={selectionAccent}
			textAlignVertical={multiline ? "top" : undefined}
			{...props}
			editable={resolved.isDisabled ? false : editable}
			onBlur={handleBlur}
			onFocus={handleFocus}
			ref={composeRefs(ref, group?.fieldRef)}
		/>
	);
}

/**
 * A text field.
 *
 * The `TextInput` this renders is uniwind's, not React Native's — uniwind's
 * Metro resolver rewrites the `react-native` import — which is what lets a
 * className drive the three props that take a colour *value* rather than a
 * style: the placeholder, the caret and the selection highlight. No
 * `withUniwind` wrapper is involved, so AGENTS.md rule 7 is untouched. Those
 * classNames must be `accent-*` utilities; see `input.variants.ts` for why.
 *
 * Focus styling is driven from React state rather than a `focus:` class.
 * Uniwind tracks focus per component, so a `focus:` utility would light up a
 * lone field and do nothing for the box `Input.Group` draws around a grouped
 * one — and the decision would sit somewhere `bun test` cannot reach.
 *
 * Everything `TextInput` accepts is accepted here, with one name removed:
 * uniwind's `placeholderTextColorClassName` is replaced by
 * `placeholderColorClassName`, so there is exactly one name for the placeholder
 * colour rather than two that can disagree.
 *
 * Wrap it in an `Input.Group` to put an icon, an affix or a control inside the
 * field's own box.
 *
 * @example
 * <Input onChangeText={setEmail} placeholder="Email" value={email} />
 *
 * @example
 * <Input isInvalid={!isValid} size="lg" variant="secondary" />
 *
 * @example
 * <Input multiline numberOfLines={4} placeholder="Notes" />
 */
export const Input = Object.assign(InputRoot, {
	/** A row that puts prefix and suffix content inside the field's own box. */
	Group: InputGroup,
	displayName: "DelacourUI.Input",
});

import type { ViewProps } from "react-native";

/**
 * The shape of a group's leading and trailing slots.
 *
 * Shared by `Input.Group.Prefix` and `Input.Group.Suffix`, which are identical
 * apart from where the row places them, so it lives in a leaf rather than in
 * one of the two files arbitrarily.
 */
export type InputSlotProps = ViewProps & { className?: string };

import type { VariantProps } from "tailwind-variants";
import { cn } from "@registry/lib/cn";
import { tv } from "@registry/lib/tv";

export const INPUT_VARIANTS = ["primary", "secondary"] as const;

export const INPUT_SIZES = ["sm", "md", "lg"] as const;

export type InputVariant = (typeof INPUT_VARIANTS)[number];
export type InputSize = (typeof INPUT_SIZES)[number];

/** Theme token an icon in a decorator inherits, and the one it takes when invalid. */
export const INPUT_DECORATOR_ICON_TOKEN = "muted-foreground";
export const INPUT_INVALID_DECORATOR_ICON_TOKEN = "danger";

/**
 * Default colours for the three `TextInput` props that take a colour rather
 * than a style — the placeholder, and the caret and selection highlight.
 *
 * These are `accent-*` utilities, not `text-*` ones, and that is not a style
 * choice. Uniwind bridges a className to one of these props by compiling it and
 * reading `styles.accentColor`, so a class that sets any other property
 * resolves to nothing: uniwind warns once in development and the prop is left
 * undefined, which reads as "the platform default" rather than as an error.
 */
export const INPUT_PLACEHOLDER_ACCENT_CLASS = "accent-muted-foreground";
export const INPUT_SELECTION_ACCENT_CLASS = "accent-primary";
export const INPUT_INVALID_SELECTION_ACCENT_CLASS = "accent-danger";

/**
 * Styling for every part of a text field.
 *
 * One slotted `tv()` rather than a call per part, so `size` and `variant` are
 * declared once — and, more importantly here, so the box is declared once. The
 * `root` slot is the whole bordered box, and it lands on the `TextInput` when
 * the field stands alone or on `Input.Group`'s row when it does not. That is
 * what makes a grouped field identical to a lone one by construction rather
 * than by two class strings happening to agree; `input.variants.test.ts` pins
 * it as a property over every combination of the axes.
 *
 * `root` therefore holds no `text-*` utility. When the field is grouped that
 * slot is worn by a `View`, and a React Native `View` does not cascade colour
 * to a `Text` descendant — so the type scale and the colour live on `field`,
 * which is always the `TextInput` itself. See AGENTS.md rule 1.
 *
 * A size names tokens rather than raw utilities: `h-input-md` for the box,
 * `text-input-md` for the value, `size-icon-md` for a decorator's glyph. The
 * values live in `tokens.css`, so a field and the icon inside it resolve
 * against one scale rather than two numbers happening to agree. `cn` and `tv`
 * both have to know these token names — see `lib/cn.ts` and `styles/tokens.ts`.
 *
 * Prefix and suffix share the one `decorator` slot. They are the same box in
 * different places, and a second identical slot is a second definition that can
 * drift.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const inputVariants = tv({
	slots: {
		root: "overflow-hidden rounded-lg border",
		/** Layout for the group's row. Never applied to a lone field, which is not a row. */
		row: "flex-row items-center",
		field: "text-foreground",
		decorator: "items-center justify-center",
		/** Edge length an `Icon` in a decorator inherits. */
		decoratorIcon: "",
		/** Treatment a bare `Text` affix in a decorator inherits. */
		decoratorText: "text-muted-foreground",
	},
	variants: {
		variant: {
			primary: { root: "border-input bg-card" },
			secondary: { root: "border-transparent bg-secondary" },
		},
		size: {
			sm: {
				root: "rounded-md px-2.5",
				row: "gap-1.5",
				field: "text-input-sm leading-tight",
				decoratorIcon: "size-icon-sm",
				decoratorText: "text-input-sm",
			},
			md: {
				root: "px-3",
				row: "gap-2",
				field: "text-input-md leading-tight",
				decoratorIcon: "size-icon-md",
				decoratorText: "text-input-md",
			},
			lg: {
				root: "px-3.5",
				row: "gap-2.5",
				field: "text-input-lg leading-tight",
				decoratorIcon: "size-icon-lg",
				decoratorText: "text-input-lg",
			},
		},
		// The empty `false` branches are load-bearing typing, not placeholders.
		// `tv` derives the prop type from the declared keys, so a map with only
		// `true` types the prop as `true` rather than `boolean` and rejects
		// `inputVariants({ isFocused })`. See button.variants.ts for the same note.
		isFocused: { true: { root: "border-ring" }, false: {} },
		isInvalid: { true: { root: "border-danger", decoratorText: "text-danger" }, false: {} },
		isDisabled: { true: { root: "opacity-50" }, false: {} },
		isMultiline: { true: {}, false: {} },
		// A grouped field shares its row, so it stretches — and it clears React
		// Native's own padding, which on Android would otherwise inset the value
		// from a gutter the row has already applied.
		isGrouped: { true: { field: "flex-1 p-0" }, false: {} },
	},
	compoundVariants: [
		// The height and the vertical rhythm are declared together rather than
		// fighting each other in the merge, the way a button's square footprint
		// and its horizontal padding are.
		//
		// `py-0` on a single-line field is load-bearing on Android: React
		// Native's `TextInput` inherits the platform's own vertical padding,
		// which would push the value off centre inside a fixed height.
		{ isMultiline: false, size: "sm", class: { root: "h-input-sm py-0" } },
		{ isMultiline: false, size: "md", class: { root: "h-input-md py-0" } },
		{ isMultiline: false, size: "lg", class: { root: "h-input-lg py-0" } },
		// A multiline field grows with its text, so the height becomes a floor.
		// The row aligns to the top with it: centred decorators would drift down
		// the side of a paragraph instead of sitting on its first line.
		{ isMultiline: true, size: "sm", class: { root: "min-h-input-sm py-2", row: "items-start" } },
		{ isMultiline: true, size: "md", class: { root: "min-h-input-md py-2.5", row: "items-start" } },
		{ isMultiline: true, size: "lg", class: { root: "min-h-input-lg py-3", row: "items-start" } },
		// Focus is transient and invalid is reported, so invalid outranks it. A
		// field that went grey the moment it was tapped would drop the only
		// signal it has that its value is wrong, exactly while it is being fixed.
		{ isFocused: true, isInvalid: true, class: { root: "border-danger" } },
	],
	defaultVariants: {
		variant: "primary",
		size: "md",
		isFocused: false,
		isInvalid: false,
		isDisabled: false,
		isMultiline: false,
		isGrouped: false,
	},
});

/** The axes that decide how a field's box is drawn, wherever that box lands. */
export type InputBoxState = {
	variant?: InputVariant;
	size?: InputSize;
	isDisabled?: boolean;
	isFocused?: boolean;
	isInvalid?: boolean;
	isMultiline?: boolean;
};

/**
 * The class the `TextInput` itself wears.
 *
 * Standalone, the field *is* the box, so it takes the chrome and the text
 * treatment together. Inside an `Input.Group` the box belongs to the row and
 * the field takes the text treatment alone — otherwise the two would draw two
 * borders, one inside the other.
 *
 * This is the single decision that keeps a grouped field indistinguishable from
 * a lone one: both read the same `root` slot, so there is no second class
 * string that could drift from the first.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveInputFieldClass({
	className,
	isGrouped = false,
	...state
}: InputBoxState & { className?: string; isGrouped?: boolean }): string {
	const slots = inputVariants({ ...state, isGrouped });
	return isGrouped ? slots.field({ className }) : cn(slots.root(), slots.field({ className }));
}

/**
 * The class `Input.Group`'s row wears: the same box a lone field would draw,
 * laid out as a row so the decorators and the field can share it.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveInputGroupClass({ className, ...state }: InputBoxState & { className?: string }): string {
	const slots = inputVariants({ ...state, isGrouped: true });
	return cn(slots.root(), slots.row({ className }));
}

/**
 * The `accent-*` class uniwind resolves the placeholder colour from.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function resolvePlaceholderAccentClass(className?: string): string {
	return cn(INPUT_PLACEHOLDER_ACCENT_CLASS, className);
}

/**
 * The `accent-*` class uniwind resolves the caret and selection colour from.
 *
 * An invalid field tints them danger along with its border, so the state is
 * still legible while the value is being corrected — the moment the border is
 * the only thing carrying it. A caller's class still wins.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function resolveSelectionAccentClass({
	className,
	isInvalid = false,
}: {
	className?: string;
	isInvalid?: boolean;
}): string {
	return cn(isInvalid ? INPUT_INVALID_SELECTION_ACCENT_CLASS : INPUT_SELECTION_ACCENT_CLASS, className);
}

export type InputVariantProps = VariantProps<typeof inputVariants>;
